/**
 * Returns a presigned GCS URL for direct upload. The client sends JSON
 * metadata here, then uploads the file directly to the returned URL.
 * @summary Request a presigned URL for file upload
 */





export const RequestUploadUrlBody = zod.object({
  "name": zod.string().min(1).describe('Original file name.'),
  "size": zod.number().min(1).describe('File size in bytes.'),
  "contentType": zod.string().min(1).describe('MIME type of the file (e.g. `image\/jpeg`).'),
  "category": zod.enum(['doctors', 'prescriptions', 'chat', 'banners', 'blog', 'shop', 'general']).optional().describe('Upload category — determines the storage subdirectory. Defaults to\n\"general\" if omitted. Use this to route files to the correct folder:\ndoctors (profile photos), prescriptions (PDFs\/lab reports),\nchat (message attachments), banners (hero\/banner images),\nblog (post cover images), shop (product images).\n')
})






export const RequestUploadUrlResponse = zod.object({
  "uploadURL": zod.string().describe('Upload destination URL for PUT upload.'),
  "objectPath": zod.string().describe('Normalized object path (e.g. `\/objects\/uploads\/doctors\/uuid`). Store this in your database.'),
  "metadata": zod.object({
  "name": zod.string().min(1).describe('Original file name.'),
  "size": zod.number().min(1).describe('File size in bytes.'),
  "contentType": zod.string().min(1).describe('MIME type of the file (e.g. `image\/jpeg`).'),
  "category": zod.enum(['doctors', 'prescriptions', 'chat', 'banners', 'blog', 'shop', 'general']).optional().describe('Upload category — determines the storage subdirectory. Defaults to\n\"general\" if omitted. Use this to route files to the correct folder:\ndoctors (profile photos), prescriptions (PDFs\/lab reports),\nchat (message attachments), banners (hero\/banner images),\nblog (post cover images), shop (product images).\n')
}).optional()
})


